package com.smartcanteen.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant;
@Entity @Table(name="food_items")
public class FoodItem { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,length=120) private String name; @Column(length=1000) private String description; @Column(nullable=false,precision=10,scale=2) private BigDecimal price; @Column(length=1000) private String imageUrl; @ManyToOne(fetch=FetchType.EAGER,optional=false) @JoinColumn(name="category_id",nullable=false) private Category category; @Column(nullable=false) private boolean available=true; @Column(nullable=false,updatable=false) private Instant createdAt=Instant.now(); @Column(nullable=false) private Instant updatedAt=Instant.now(); @PreUpdate void touch(){updatedAt=Instant.now();} public Long getId(){return id;} public String getName(){return name;} public void setName(String v){name=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public BigDecimal getPrice(){return price;} public void setPrice(BigDecimal v){price=v;} public String getImageUrl(){return imageUrl;} public void setImageUrl(String v){imageUrl=v;} public Category getCategory(){return category;} public void setCategory(Category v){category=v;} public boolean isAvailable(){return available;} public void setAvailable(boolean v){available=v;} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;} }
